export function authorizeVoiceToolCall(call: LiveSpeechToolCall): VoicePermissionResult {
	const decision = evaluateToolPermission({
		tool: classifyTool(call.name),
		surface: "voice",
		provenance: { trust: "unknown", userAuthorized: false },
		arguments: call.arguments,
	});
	if (decision.outcome === "allow") return { allowed: true };
	return {
		allowed: false,
		reason: decision.outcome === "confirm"
			? `Voice tool "${call.name}" needs confirmation in typed chat.`
			: `Voice tool "${call.name}" is not permitted.`,
	};
}
